function createExpensiveCalc() {
  const cache = {}; // Preserved via closure

  return function(num) {
    if (cache[num]) {
      return `Cache: ${cache[num]}`;
    }
    // Expensive operation (e.g., calculation)
    const result = num * 2;
    cache[num] = result;
    return `Calculated: ${result}`;
  };
}

const calculate = createExpensiveCalc();
